**Check context and video-buffer construction before first use.**

Line 155 and Lines 178-179 can return `NULL`. The current flow dereferences these pointers immediately (`vl_create_h264_decoder`, `upload_luma`, `upload_chroma`), which crashes on setup failure.

<details>
<summary>Proposed fix</summary>

```diff
    struct pipe_context *ctx = screen->context_create(screen, NULL, 0);
+   if (!ctx) {
+      fprintf(stderr, "vl-h264-decode-frame: context create failed\n");
+      screen->destroy(screen);
+      winsys->destroy(winsys);
+      return 77;
+   }
@@
    struct pipe_video_buffer *target = make_buffer(ctx);
    struct pipe_video_buffer *reference = make_buffer(ctx);
+   if (!target || !reference) {
+      fprintf(stderr, "vl-h264-decode-frame: video buffer create failed\n");
+      if (target) target->destroy(target);
+      if (reference) reference->destroy(reference);
+      dec->destroy(dec);
+      free(refbuf);
+      ctx->destroy(ctx);
+      screen->destroy(screen);
+      winsys->destroy(winsys);
+      return 1;
+   }
```
</details>






