**Reject size-probe failures before allocating.**

`read_file()` uses `ftell()` as the allocation count without checking whether the seek/size probe succeeded. If either call fails, `-1` is widened to a huge `size_t`, so the test reports an allocation/read failure instead of the real I/O fault. Harden this helper here and in `src/gallium/auxiliary/vl/tests/vl_h264_intra_luma_test.c`.

<details>
<summary>Proposed fix</summary>

```diff
 static uint8_t *
 read_file(const char *path, long *size)
 {
-   FILE *f = fopen(path, "rb");
-   if (!f)
+   FILE *file = fopen(path, "rb");
+   if (!file)
       return NULL;
-   fseek(f, 0, SEEK_END);
-   *size = ftell(f);
-   fseek(f, 0, SEEK_SET);
-   uint8_t *data = malloc(*size);
-   if (data && fread(data, 1, *size, f) != (size_t)*size) {
+   if (fseek(file, 0, SEEK_END) != 0) {
+      fclose(file);
+      return NULL;
+   }
+
+   *size = ftell(file);
+   if (*size < 0 || fseek(file, 0, SEEK_SET) != 0) {
+      fclose(file);
+      return NULL;
+   }
+
+   uint8_t *data = malloc((size_t)*size);
+   if (data && fread(data, 1, (size_t)*size, file) != (size_t)*size) {
       free(data);
       data = NULL;
    }
-   fclose(f);
+   fclose(file);
    return data;
 }
```
</details>

